Matching Ayahs
- = Алиф, Лам, Мим. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Алар Раббилеринен келген туура жолдо, жана алар – ийгиликке жетүүчүлөр. 2:5; 31:5
- = Оо, Ысрайыл уулдары! Мен силерге берген ырыскымды жана Мен силерди ааламдардын (элдердин) үстүнөн артык кылганымды эстегиле. 2:47; 2:122
- = Бул – өтүп кеткен бир үммөт. Ага өзүнүн иштегени, силерге өзүңөрдүн иштегениңер. Силер алардын иштегендеринен суралбайсыңар. 2:134; 2:141
- = Алар анда түбөлүк калышат. Азап алардан жеңилдетилбейт жана аларга дем берилбейт. 2:162; 3:88
- = Бирок андан кийин тообо кылып, өздөрүн оңдогондор башка. Чынында Аллах – Кечирүүчү, Ырайымдуу. 3:89; 24:5
- = Ал эми каапыр болуп, аяттарыбызды жалганга чыгаргандар – алар тозоктун ээлери. 5:10; 5:86
- = Аларга Раббилеринин белгилеринен бир белги келсе, алар андан бет бурушат. 6:4; 36:46
- = Сенден мурун да пайгамбарлар масхараланган. Анан аларды масхаралагандарды, өздөрү келеке кылган нерсе курчап алган. 6:10; 21:41
- = Айт: "Эгер мен Раббиме күнөө кылсам, Улуу күндүн азабынан коркомун." 6:15; 39:13
- = Анан аларды жер титирөө кармап, үйлөрүндө жүзүн жерге салып калышты. 7:78; 7:91
- = Анан ал (Муса) таягын ыргытты, ошол замат ал ачык ажыдаар болду. 7:107; 26:32
- = Жана ал колун чыгарды, ошол замат ал карагандарга аппак (жарык) болду. 7:108; 26:33
- = Алар айтышты: "Биз ааламдардын Раббисине ишендик." 7:121; 26:47
- = Муса менен Харундун Раббисине. 7:122; 26:48
- = Мен аларга дем беремин. Чынында, Менин айла-амалым бекем. 7:183; 68:45
- = Ал Өз Пайгамбарын туура жол жана чын диний менен жиберген – аны бардык диндерден үстөн кылуу үчүн, эгер мушриктер жаман көрсө да. 9:33; 61:9
- = Оо, Пайгамбар! Каапырларга жана эки жүздүүлөргө каршы согуш, аларга катаал бол! Алардын башпаанеги – Жаханам, жана ал кандай жаман кайт! 9:73; 66:9
- = Алар айтышат: "Эгер чынчыл болсоңор, бул убада качан?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Биз Мусаны белгилерибиз жана ачык далил менен жибердик. 11:96; 40:23
