- Ал аны бейиштерге киргизет, астынан дарыялар агып турат, алар анда түбөлүк калышат. (يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 4:13; 4:57; 4:122; 58:22; 64:9; 65:11
- Кыямат күнү алардын арасында талашкан нерселерине өкүм чыгарылат. (بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 10:93; 16:124; 22:69; 32:25; 45:17
- Алар жер жүзүн кыдырып, акыбети кандай болгонун көрүшпөдүбү? (أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 30:9; 35:44; 40:21; 40:82; 47:10
- Бейиштер, астынан дарыялар агып турат, алар анда түбөлүк калышат. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 5:119; 64:9; 65:11
- Сен түндү күнгө киргизесиң, күндү түнгө киргизесиң. (تُولِجُ اللَّيْلَ فِي النَّهَارِ وَتُولِجُ النَّهَارَ فِي اللَّيْلِ) 3:27; 22:61; 31:29; 35:13; 57:6
- Асмандардагы жана жердеги бардык нерсе Аллахты даңазалайт. (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 59:1; 61:1; 62:1; 64:1
- Аллахка кулчулук кылгыла, силерде Андан башка кудай жок. Коркпойсуңарбы? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23; 23:32
- Периштелерге: Адамга сажда кылгыла! – дегенибизде, Иблистен башка баары сажда кылды. (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ) 2:34; 17:61; 18:50; 20:116
- Аллах асмандардагы жана жердеги нерселерди билет. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 3:29; 5:97; 49:16; 58:7
- Бейиштер, астынан дарыялар агып турат, алар анда түбөлүк калышат, жана ал. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ) 4:13; 5:85; 9:89; 57:12
- Анын сыйлыгы Раббисинин алдында, аларга коркунуч жок, жана алар. (أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:112; 2:262; 2:274; 2:277
- Раббисинин алдында, аларга коркунуч жок, жана алар кайгырышпайт. (عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:112; 2:262; 2:274; 2:277
- Ким туура жолго түшсө, ал өзү үчүн түшөт, ал эми ким адашса. (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- Өзү үчүн түшөт, ал эми ким адашса, ал өз зыянына адашат. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- Ага Раббиси тарабынан эмне үчүн бир белги түшүрүлбөдү? Айт: Чынында. (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- Ыйман келтирип, жакшы амалдарды кылгандарга үзгүлтүксүз сыйлык бар. (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- Сен тирүүнү өлүктөн чыгарасың, өлүктү тирүүдөн чыгарасың. (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- Ким Аллах түшүргөн нерсе менен өкүм кылбаса, так ошолор. (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- Ал асмандарды, жерди жана алардын арасындагыларды алты күндө жаратты. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- Чынында, Аллах адамдарга кеңчилик ээси, бирок көпчүлүгү. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- Аллах аларга залымдык кылган жок, бирок алар өздөрүнө залымдык кылышты. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- Ал силердин күнөөлөрүңөрдү кечирип, астынан дарыялар аккан бейиштерге киргизет. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- Ал силерге өлүм, кан, чочконун этин жана Аллахтан башканын атына союлган нерсени арам кылды. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- Мен, эгер Раббиме күнөө кылсам, Улуу күндүн азабынан корком. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- Бирок аларга илим келгенден кийин, араларындагы көрө албастыктан. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- Алар намазды толук орундашат жана Биз берген ырыскыдан жашыруун жана ачык садака беришет. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- Аллахтан башка, бизге пайда да, зыян да келтире албаган нерсеге дуба кылабызбы? (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- Алар сага түшүрүлгөнгө жана сенден мурун түшүрүлгөнгө ыйман келтиришет. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- Аллахтын асмандан суу түшүргөнүн көрбөйсүңбү? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- Бир ишти каалаганда, ага: Бол! – дейт, ошондо ал болот. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- Мадянга алардын бир тууганы Шуайбды (жибердик). Ал айтты: Оо, элим! Аллахка кулчулук кылгыла. (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- Бул кайып кабарлардан, аны сага вахий кылып жатабыз; сен муну билчү эмессиң. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- Алардын мөөнөтү келгенде, аны бир саатка да кечиктире алышпайт жана илгерилете да алышпайт. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- Шайтандын изинен ээрчибегиле, ал силерге анык душман. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- Адамдардын арасында илимсиз Аллах жөнүндө талашкандар бар. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- Аллах аны каалаган адамына берет, Аллах кеңири кенчилдик ээси. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- Ар бир жан өзүнүн кылганына толук сыйлык алат, жана аларга залымдык кылынбайт. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- Аллах арам кылган жанды, аксыз өлтүрбөгүлө. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- Бир ишти каалаганда, ага: Бол! – дейт. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- Тозактын дарбазаларынан киргиле, анда түбөлүк каласыңар; текеберлердин орду кандай жаман! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- Китептен үлүш берилгендерди көрбөйсүңбү? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- Аларга астынан дарыялар аккан бейиштер бар, алар анда түбөлүк калышат. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- Оо, элим! Өзүңөрдүн абалыңарга жараша иш кылгыла, мен да иш кылам, жакында билесиңер. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- Ким Аллахка жана Анын Элчисине каршы чыкса, ага тозак оту бар, ал анда түбөлүк калат. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- Биз алардын жүрөктөрүнө тосмолорду коюп, аны түшүнбөсүн үчүн, кулактарына дөбөстүк койдук. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- Биз эскертүүчү жиберген ар бир айылдын байлары: Биз. – дешти. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- Алар: Раббиңден биз үчүн сура, ал бизге эмне экенин тактап берсин. – дешти. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- Алар: Аллах. – дешет. Сен айт: Бардык мактоо Аллахка таандык! Бирок алардын көпчүлүгү. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- Анын элинин жообу: Аларды кууп чыгаргыла. – деген гана болду. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- Астынан дарыялар агып турат, алар анда түбөлүк калышат; бул чоң ийгилик. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- Ошолор Раббисинин туура жолунда, жана так ошолор ийгиликке жетүүчүлөр. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- Кимге кордук азабы келет жана кимге түбөлүк азап келет. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- Жер жүзүн кыдырып, жалганга чыгаруучулардын акыбети кандай болгонун көргүлө. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- Алар өздөрүнүн колдору жасаган иштерден улам, аны эч качан каалашпайт, Аллах залымдарды билет. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- Ал кимдин Өз жолунан адашканын эң жакшы билет, жана Ал эң жакшы билет. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- Чынында, Аллах менин Раббим жана силердин Раббиңер, анда Ага кулчулук кылгыла; бул туура жол. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- Ал адамдарга кеңчилик ээси, бирок алардын көпчүлүгү шүгүр кылышпайт. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- Асмандарды, жерди жана алардын арасындагыларды чындык жана белгиленген мөөнөт менен гана жараттык. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- Аларды койгула, алар убада кылынган күнүнө жолукканга чейин, бош сөзгө чөмүлүп ойношсун. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- Алар ыйман келтиргендерге жолукканда: Ыйман келтирдик. – дешет, ал эми өздөрү жеке калганда. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- Алар Тооратты, Инжилди жана Раббиси тарабынан түшүрүлгөндү толук аткарышат. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- Ал алардын алдындагыны жана артындагыны билет, ал эми алар аны илим менен камтый алышпайт. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- Жана Ал асмандарды жана жерди алты күндө жараткан. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- Чынында, бул аятта силерге белги бар, эгер ыйман келтирген болсоңор. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- Адамдарга туура жол келгенде, эмне аларды ыйман келтирүүдөн тосту? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- Алар Аллахка шерик кошуп, Анын жолунан адаштыруу үчүн. Айт: Көңүл ачкыла. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- Алар өздөрүнөн эскертүүчү келгенине таң калышып, каапырлар: Бул. – дешти. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- Чынында, Раббиң кимдин Өз жолунан адашканын эң жакшы билет. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- Мал-мүлкүн адамдарга көрсөтүү үчүн жумшап, Аллахка ыйман келтирбеген адам сыяктуу. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- Биз силерге берген ырыскыдан, ал келгенге чейин садака бергиле. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- Ал асмандардагы жана жердеги нерселерди силерге баш ийдирди. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- Жана биз силер чакырган нерсеге күмөн санап жатабыз. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- Чынында, Раббиң каалаган адамына ырыскыны кеңири берет жана тар кылат. Чынында, Ал. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- Асмандардын жана жердин жана алардын арасындагылардын Раббиси, эгер ишенген болсоңор. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- Биз Аллахка, бизге түшүрүлгөнгө жана Ибрахимге, Исмаилге, Исхакка, Жакыпка жана анын тукумдарына түшүрүлгөнгө ыйман келтирдик. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- Залымдарды катуу үн кармап, алар өз үйлөрүндө чөгөлөп калышты. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- Алардын өздөрү жөнүндө кылган иштери үчүн силерге күнөө жок. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- Раббиң кимдин Өз жолунан адашканын эң жакшы билет, жана Ал. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- Өз амири менен рухту (вахийди) каалаган кулуна түшүрөт. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- Жана Биз Мариямдын уулу Исага анык белгилерди бердик жана аны Ыйык Рух менен колдооду. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- Кыямат күнү алардын арасында талашкан нерселерине өкүм чыгаруу үчүн. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- Биз аны (айылды) төңкөрүп, үстүнө күйгүзүлгөн чопо таштарды жаадырдык. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- Аларга эскертсең да, эскертпесең да бирдей, алар ыйман келтиришпейт. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- Адамдардан башка, эгер чынчыл болсоңор, өлүмдү каалагыла. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- Аллах, силерде Андан башка кудай жок. Коркпойсуңарбы? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- Биз аларга убада кылган нерсенин кээ бирин сага көрсөтсөк да, же сени өлтүрсөк да, алар Бизге кайтып келет. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- Алар: Биз өлүп, топурак жана сөөк болгондо, чынында кайра тирилебизби? – дешти. (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- Кеңчилик Аллахтын колунда, Ал аны каалаган адамына берет, Аллах. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- Жана силер көрүнгөн жана көрүнбөгөн нерселерди Билүүчүгө кайтарыласыңар, ал силердин кылган иштериңерди билдирет. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- Оо, ыйман келтиргендер! Аллахтын силерге берген ныгматын эске алгыла, ошол кезде. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- Сенден мурун да Биз вахий түшүргөн эркектерди гана Элчи кылып жибердик. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- Ал анын күнөөлөрүн кечирип, астынан дарыялар аккан бейиштерге киргизет. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- Оорулуу же сапарда болгон адам, башка күндөрдө эсебин толтурсун. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- Алар ой-жоромолго гана ээришет жана алар болжолдошот. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- Аллахка жана Акырет күнүнө үмүт кылгандарга жакшы үлгү бар. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- Асмандарды, жерди жана алардын арасындагыларды чындык менен гана жараттык. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- Колуңду койнуңа сал, ал эч кандай кемчиликсиз аппак болуп чыгат. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- Ал Өз ырайымы менен каалаган адамын айырмалайт, Аллах кеңири кенчилдик ээси. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- Аллах асмандардын жана жердин падышачылыгынын ээси экенин билбейсиңби? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- Өзүңөр үчүн алдын ала жиберген ар кандай жакшылыкты Аллахтын алдынан табасыңар. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- Кайдан чыксаң да, жүзүңдү Масжид аль-Харамга буругула. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- Сенден мурункулар өтүп кетишкен, Аллахтын жолунда эч кандай өзгөрүү таппайсың. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- Асмандардагы жана жердеги нерселердин бардыгы Ага таандык. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- Эч бир аял кош бойлуу болбойт жана төрөбөйт, бирок Анын илими менен гана. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- Ал түндү, күндү, айды жана күндү баш ийдирди; баары белгиленген мөөнөткө чейин жүрөт. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- Астынан дарыялар агып турат, алар анда түбөлүк калышат, бул сыйлык. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- Ал айтты: Жок, силердин өзүңөрдүн көңүлүңөр бир ишти кызыктырды; сабыр кылуу жакшы. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- Асмандардагы жана жердеги нерселер, жана Аллах. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- Аларга Элчи келген сайын, алар аны масхара кылышты. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- Алар: Оо, Муса! Сен таштайсыңбы, же биз таштайбызбы? – дешти. (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- Ал силерди өлтүрөт, жана силердин кээ бирлериңерди эң начар куракка кайтарылат, ошондо. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- Аларга Раббисинин алдында астынан дарыялар аккан бейиштер бар, алар анда түбөлүк калышат. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- Жана Биз алардын жүрөктөрүнө тосмолорду коюп, аны түшүнбөсүн үчүн, кулактарына дөбөстүк койдук. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- Аллахтын убадасы чындык, бирок алардын көпчүлүгү билишпейт. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- Бул алардын Аллахка жана Анын Элчисине каршы чыккандыгынан; Аллахка каршы чыккан адамга. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- Ал күнү Ал аларды чакырып: Менин шериктерим деп эсептегениңер кайда? – дейт. (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- Алар Аллахтын асмандарды жана жерди жаратканын көрүшпөдүбү? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (Ал) силерди топурактан, андан кийин бир тамчы урлуктан, андан кийин. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- Алар: Раббибиз, бизге Элчи жибербедиңби, ошондо аяттарыңа ээрчимекбиз? – дешмек. (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- Андан кийин алар Раббисине кайтарылат, ал алардын кылган иштерин билдирет. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- Алардын бул жөнүндө эч кандай илими жок, алар ой-жоромолго гана ээришет. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- Биз ата-бабаларыбызды бир динде таптык, биз алардын изинен барабыз. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- Китеп берилгендер, аларга илим келгенден кийин гана (талашты). (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- Ибрахим: Раббим, бул шаарды коопсуз кыл! – дегенде. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- Ал силерге угуу, көрүү жана жүрөктөрдү берди; аз эле шүгүр кыласыңар. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- Аллахтын аяттары жөнүндө эч кандай далилсиз талашкандар. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- Ибрахимдин ханиф динине ээрчигиле, ал Аллахка шерик кошуучулардан эмес эле. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- Силерди Фараондун адамдарынан куткарганыбызда, алар силерге катуу азап беришкен. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- Бул туура дин, бирок адамдардын көпчүлүгү билишпейт. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- Аллахтын силерге асмандардагы жана жердеги нерселерди баш ийдиргенин көрбөйсүңбү? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- Каапырлар: Бул анык сыйкырдан башка эч нерсе эмес. – дешмек. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- Аларга анык аяттарыбыз окулганда, каапырлар: – дешет. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- Түбөлүк бейиштер, астынан дарыялар агып турат, алар анда түбөлүк калышат. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- Ал каалаган нерсесин жаратат; Аллах ар нерсеге кудуреттүү. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- Күнөөлөрүңөрдү кечирип, белгиленген мөөнөткө чейин кечиктирүү үчүн. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- Бизди ата-бабаларыбыз сыйынган нерседен тоскусуңар келеби? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- Раббиң периштелерге: Мен чоподон адам жаратамын. – дегенде. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- Ал Өз ырайымынан мурун шамалдарды куш кабар кылып жиберет. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- Айт: Жер жүзүн кыдырып, акыбет кандай болгонун көргүлө. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- Асмандардын жана жердин жаратылышында, түн менен күндүн алмашуусунда (белгилер бар). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- Ким Аллахка жакшы карыз берет, ал аны бир нече эсе арттырып берет? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- Алардын арасында Аллах түшүргөн менен өкүм кыл, алардын каалоолоруна ээрчибе. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- Алар периштелердин келишин же Раббиңдин амиринин келишин күтүшөбү? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- Чынында, Аллахка каршы жалган айткандар ийгиликке жетпейт. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- Фараондун адамдары жана алардан мурункулар сыяктуу, алар аяттарыбызды жалганга чыгарышты. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- Ал ыйман келтирип, жакшы амалдарды кылгандарга, аларга сыйлык болоорун кубаттуу кабар кылат. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- Аллах каалаган кулуна ырыскыны кеңири берет жана тар кылат. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- Жана силер көрүнгөн жана көрүнбөгөн нерселерди Билүүчүгө кайтарыласыңар, ал силердин кылган иштериңерди билдирет. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- Жакын туугандар Аллахтын Китебинде бири-бирине жакыныраак. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — милдеттүү (аткаруу керек; таштаса күнөө)
- mustahabb / mandub (مستحب / مندوب) — сунушталган (аткарса сооп, таштаса күнөө эмес)
- mubah (مباح) — бейтарап / уруксат (сообу да, күнөөсү да жок)
- makruh (مكروه) — жагымсыз (сунушталбайт, бирок аткарса күнөө эмес)
- haram (حرام) — тыюу салынган (аткаруу күнөө)
- halal (حلال, уруксат / мыйзамдуу) — мубах жана мустахабды камтыйт — тыюу салынбаган нерселердин баары
- Аллахка гана ибадат кылыңыз жана Андан жардам/колдоо сураңыз. 1:5
- Аллахка гана ибадат кылыңыз. 2:21
- Аллахка эч кандай шерик кошпогула. 2:22
- Аллах — кечирүүчү (тобону кабыл алуучу), Ал Адамдын (ага салам) тобосун кабыл алды. 2:37
- Чындыкты жалган менен аралаштырбагыла жана чындыкты жашырбагыла. 2:42
- Намазды (күнүмдүк намаздарды) аткарыңыз жана зекетти (кайыр-садага) бериңиз. 2:43
- Өзүңөр аткаргандан кийин гана башкаларга жакшылыкты буйруңар. 2:44
- Бардык ишиңерде Аллахтан жардам сурагыла. 2:45
- Бузукулукка аралашпагыла жана аны жайбаштабагыла. 2:60
- Адамдарды ибадатканаларга барууга тоскоол болбогула. 2:114
- Мечиттин ыйыктыгын урматтагыла. Намаз окуган жерлериңерди таза жана пакиз кармагыла. 2:125
- Аллахты эстегиле (намаз, тасбих ж.б. менен), Ал силерди эстейт, жана Ага шүгүр кылыгыла. 2:152
- Кыйынчылыктарда сабырдуу болгула. 2:153
- Шайтандын изи менен жүрбөгүлө, ал анык душман. 2:168
- Эч кимге сокур ээрчибегиле. 2:170
- Бардык аманаттарды сактагыла жана аткаргыла. Диний милдеттериңерди чын ыклас менен аткаргыла. Анттарыңарды жана убадаларыңарды аткаргыла. Убадаларды, өзгөчө Аллахка берген убадаларыңарды сактагыла. Муктаждарга колдоо көрсөткүлө жана кыйынчылыктарды жеңилдеткиле. Кудайдын ырайымынан ажырата турган күнөөлөрдү жасоодон сактангыла. Текеберчилик силерди адилетсиздикке алып барбасын. 2:177
- Кисаста (жазалоодогу теңдик мыйзамы) силер үчүн өмүр бар. 2:179
- Рамазан айында орозо кармагыла. Такыбалар (Муттакиун) болуу үчүн белгиленген орозону кармагыла. 2:183
- Куранды акыркы жол көрсөтүү булагы катары урматтагыла. 2:185
- Бири-бириңердин малын адилетсиз жемегиле жана сотторго (ишиңерди тапшырганга чейин) пара бербегиле. 2:188
- Башкаларга сөз же иш менен зомбулук кылбагыла. Эч качан баскынчы катары согушпагыла, тек гана коргонуу үчүн. 2:190
- Жетимдерди коргогула. Жетимдерге келсек, алардын малына адилеттүү мамиле кылып, алардын малын жемегиле. 2:220
- Тобо кылып, Аллахтан кечирим сурагыла. Этек кир мезгилинде жыныстык катнашка барбагыла. Тазалыкты (дене жана рух) сактагыла. 2:222
- Үй-бүлөңөргө болгон милдеттериңерди аткаргыла. 2:233
- Жетекчилерди алардын эмгегине жараша тандагыла. 2:247
- Динде зордук-зомбулук жок. 2:256
- Мал-мүлкүңөрдү кайыр-садагага жумшагыла. Малда да, убакытта да жомарт болгула. 2:261
- Өз жомарттыгыңарды мактаныш менен бузбагыла. 2:264
- Шайтан силерди жакырчылык менен коркутат жана силерге фахшаны (жаман иштерди, мыйзамсыз жыныстык катнашты, күнөөлөрдү) буйруйт. 2:268
- Муктаждарды издегиле жана аларга жардам бергиле. 2:273
- Риббага (суунун пайызына) аралашпагыла. Пайыздуу малды жемегиле. Риббаны (пайызды) жемегиле. 2:275
- Эгер карыздар кыйын абалда болсо, төлөөгө көбүрөөк убакыт бергиле. 2:280
- Соода бүтүмдөрүндө сөзүңөрдө тургула. Каржы иштериңерде чынчыл болгула. Бардык милдеттенмелериңерде адилеттүү болгула. Белгиленген мөөнөткө карыз келишимин түзгөндө, аны жазып койгула. Соода келишимин түзгөн сайын күбөлөрдү алгыла. 2:282
- Бардык аманаттарды сактагыла жана аткаргыла. 2:283
- Түшүрүлгөн Китептерге жана бардык Пайгамбарларга ишенгиле. 2:285
- Аллах эч кимге анын күчү жетпеген нерсени жүктөбөйт. Адам өзүнүн жакшы иштеринин сообун алат жана жаман иштеринин жазасын тартат. Аллах эч кимге анын күчүнөн ашык жүк жүктөбөйт; биз да андай кылбоого тийишпиз. Кыйынчылыкта да Аллахтын планына ишенгиле. 2:286
- Ким убадаларды аткарса жана Аллахтан корксо, Аллах такыбаларды сүйөт. 3:76
- Эгер мүмкүнчүлүгүңөр болсо, ажылыкты (ажылыкты) аткаргыла. 3:97
- Бөлүнүп кетпегиле. 3:103
- Жакшылыкты буйругула жана жамандыкка тыюу салгыла. Коомуңарда адилеттикти кубаттагыла. Башкаларды Аллахты эскерүүгө чакыргыла. 3:104
- Момундар Аллахка гана төкөлдөшү керек. 3:122
- Риббаны (пайызды) жемегиле. 3:130
- Ырайымга ээ болуу үчүн Аллахка жана Анын Элчисине моюн сунгула. 3:132
- Аллах (Аллахтын жолунда — кайыр-садага, жакшылык иштери ж.б.) байлыкта да, кедейликте да чыгым кылгандарды, каарын жутуучуларды жана адамдарды кечирүүчүлөрдү сүйөт. 3:134
- Каарыңарды жутугула. Ачууңарды көзөмөлдөгүлө. 3:134
- Башкалардын каталарын кечирип, кечиримдүү болгула. 3:135
