- Эгер Аллах силерге жардам берсе, эч ким силерди жеңе албайт; эгер Ал силерди таштап койсо, Андан кийин силерге ким жардам бере алат? 3:160
- Ар бир жан өлүмдү татат. Жана Тирилүү күнүндө гана толук соопторуңарды аласыңар. 3:185
- Жаратылыштын кереметтери жана бул ааламдын жаратылышы жөнүндө терең ой жүргүзгүлө. Аллах ааламды маани жана максат менен жараткандыгын билгиле. 3:191
- Эркектер жана аялдар иш-аракеттери үчүн бирдей сооп алышат. 3:195
