- Ар бир иш-аракетте ар дайым Аллахтын ыраазычылыгын көздөгүлө. 3:200
- Раббиңерден корккула, Андан кайдан корккула жана (туугандык) байланыштарды үзбөгүлө. 4:1
- Жетимдерге алардын малын бергиле жана (өзүңөрдүн жаманыңарды) алардын (жакшысына) алмаштырбагыла; жана алардын малын (өз малыңарга кошуп) жемегиле. 4:2
- (Үйлөнүп жаткан) аялдарыңарга алардын махр (үйлөнүү убагында күйөөсүнүн аялына берүүгө милдеттүү болгон байгесин) жакшы ниет менен бергиле. 4:4
- Жетимдердин укуктарын коргогула. 4:6
- Өлгөн адамдын мүлкү анын үй-бүлө мүчөлөрүнө бөлүштүрүлүшү керек. Аялдардын мураскорлук укугу бар. 4:7
- Жетимдердин малын адилетсиз жемегиле. 4:10
- Мураскорлукка байланыштуу буйруктарды аткаргыла. 4:11
- Аялдарды алардын каалоосуна каршы мураскор кылууга тыюу салынат, жана аларга катаал мамиле кылбагыла. Алар менен (аялдар менен) жакшы мамиледе болгула. Аялдардын укуктарын урматтап, сактагыла. Жубайыңарга боорукердик жана мээримдүүлүк менен мамиле кылгыла. Аялдарга абийир жана адилеттүүлүк менен мамиле кылгыла. 4:19
- Өзүңөргө кан тууган болгондорго үйлөнбөгүлө. 4:23
