- Эгер силер тыюу салынган чоң күнөөлөрдөн сактансаңар, Аллах силердин (кичине) күнөөлөрүңөрдү кечирип, силерди урматтуу орунга (Бейишке) киргизет. 4:31
- Аллах кээ бириңерди башкалардан артык кылган нерселерди көздөбөгүлө. Көрө албастыктан жана көз аламандыктан сактангыла. 4:32
- Эркектер аялдардын коргоочулары жана жетекчилери, анткени Аллах алардын кээ бирөөсүн башкалардан артык кылган жана алар (аялдарга) мал-мүлкүнөн чыгымдашат. Эркек үй-бүлөнүн коргоочусу жана таянычы. 4:34
- Аллахка ибадат кылыгыла жана Ага эч нерсени шерик кошпогула, ата-энеге, туугандарга, жетимдерге, жакырларга, кошунага, жолдошуңа, саякатчыга (жолукканга) жана колуңар ээ болгондорго (кулдарга) жакшылык кылгыла. Аллах текебер жана мактанчаактарды сүйбөйт. Башкаларга жакшылык кылгыла. Алсыздарга боорукер болгула. Үй-бүлөлүк байланыштарды сактагыла жана туугандарды урматтагыла. 4:36
- Бакыл болбогула. 4:37
- Аллах Өзүнө шерик кошууну кечирбейт, бирок андан башканы каалаганына кечирет. 4:48
- Башкаларга көз аламан болбогула. 4:54
