- Момунга момунду өлтүрүү туура эмес, бирок каталык менен болсо башка. 4:92
- Ким момунду атайылап өлтүрсө, анын жазасы — тозок, ал анда түбөлүккө калат. Аллахтын каары жана каргышы анын үстүндө, жана ага чоң азап даярдалган. 4:93
- Ким Аллахтын жолунда (үйүнөн) көчүп кетсе, жер бетинде көп башпаанек жана кенчилдик табат. 4:100
- Намаздарыңарды убагында аткаргыла. 4:103
