- Аллахтан кечирим сурагыла, Аллах кечирүүчү, ырайымдуу. 4:106
- Ой, ишенгендер! Адилеттүүлүктө бекем тургула, Аллах үчүн күбө болгула, эгер өзүңөргө, ата-энеңерге же туугандарыңарга каршы болсо да, бай же жакыр болсо да. Адилеттүүлүктү кечиктирбегиле; каталарды оңдоо үчүн дароо иш кылгыла. 4:135
