- Аллахка жакындаштын жолдорун издегиле жана Анын жолунда колуңардан келишинче күрөшкүлө. Ийгиликке жетүү үчүн. 5:35
- Анттарыңарды жана убадаларыңарды аткаргыла. 5:89
