- (Адамдар) бардык күнөөлөрдү, ачык жана жашыруун, таштагыла. 6:120
- (Момундар) үстүнө Аллахтын аты (мал союлганда) айтылбаган (эттен) жемегиле. 6:121
- Аллах кимди туура жолго салгысы келсе, анын көкүрөгүн Ислам үчүн кеңейтет; ал эми кимди адаштыргысы келсе, анын көкүрөгүн тар жана кысылып калган кылат. 6:125
- Чыгымдарда орточо болгула жана ысырапчылыктан алыс болгула. Бардык жандыктардын укуктарын коргогула. 6:141
- Аллахка эч нерсени шерик кошпогула, ата-энеге жакшылык кылгыла, жакырчылыктан коркуп балдарыңарды өлтүрбөгүлө, жийиркеничтүү иштерге жакындабагыла, Аллах тыюу салган жанды өлтүрбөгүлө, бирок ак ниеттүү себеп менен гана. 6:151
- Чынчыл болгула; эч бир бүтүмүңөрдө алдабагыла. Жетимдин малына жакындабагыла, бирок аны жакшыртуу үчүн гана, өлчөөнү жана таразаны адилеттүүлүк менен толук аткаргыла, сүйлөгөндө, атүгүл жакын тууганыңа тиешелүү болсо да, чындыкты айткыла жана Аллахтын убадасын аткаргыла. 6:152
- Туура жол менен жүргүлө жана (башка) жолдор менен жүрбөгүлө, анткени алар силерди Анын жолунан ажыратышат. 6:153
- (Мухаммед) айт: "Чынында, менин намазым, менин курмандыгым, менин жашоом жана менин өлүмүм — ааламдардын Раббиси Аллах үчүн." 6:162
