- Бардык иштерде Аллах белгилеген чектерди сактагыла. Сөз жана иш-аракетте чектен чыкпагыла. Жегиле жана ичкиле, бирок ысырап кылбагыла. Намаз убагында жакшы кийимдерди кийгиле. 7:31
- Аллах асмандарды жана жерди алты күндө жаратып, андан кийин Аршка (Өзүнүн Улуулугуна ылайыктуу түрдө) орношту. 7:54
