- Жер бетиндеги иреттен кийин анда бузукулук кылбагыла жана Андан коркуп, үмүттөнүп жалбарыңар. 7:56
- Ал эми жаман иш кылып, андан кийин тобо кылып, ишенгендерге, чынында, Раббиң ушундан кийин кечирүүчү, ырайымдуу. 7:153
- (Мухаммед) айт: "Ой, адамдар! Чынында мен силердин баарыңарга Аллахтын Элчисимин…" 7:158
