- (Душман) күчүнө жолукканда, бекем болгула жана Аллахтын ысымын көп эстегиле (тил жана жүрөк менен), ийгиликке жетүү үчүн. 8:45
- Текебердик жана адамдарга көрүнүш үчүн үйлөрүнөн чыккандарга окшобогула, жана (адамдарды) Аллахтын жолунан тоскондорго. 8:47
- Аллах бир элге берген ырайымын, алар өздөрүндөгүн өзгөртмөйүнчө, өзгөртпөйт. 8:53
- Аллахтын алдындагы эң жаман жандыктар — каапырлар. 8:55
- Аллах Өзүнө ишенгендердин жүрөктөрүнүн арасына сүйүү жана ынтымак салат. 8:63
- Коргоо сурагандарды коргогула жана жардам бергиле. 9:6
